<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {request,upload} from '@/integration/service';import {useUserStoreHook} from '@/store/modules/user';import GitCalendar from '@/integration/GitCalendar.vue';
const p=ref(null),busy=ref(false),password=ref({old:'',password:''}),me=useUserStoreHook();onMounted(async()=>p.value=await request('/api/studio/profile'));
async function save(){busy.value=true;try{p.value=await request('/api/studio/profile','PUT',p.value);me.SET_NICKNAME(p.value.name);me.SET_AVATAR(p.value.avatar);window.dispatchEvent(new CustomEvent('lin-theme',{detail:p.value.theme}));ElMessage.success('个人设置已保存');}catch{}finally{busy.value=false;}}
async function avatar(e){const f=e.target.files[0];if(!f)return;busy.value=true;try{p.value.avatar=(await upload(f)).result.url;}catch{}finally{busy.value=false;e.target.value='';}}
async function changePassword(){try{await request('/api/private/password','POST',password.value);password.value={old:'',password:''};ElMessage.success('密码已更新，其他登录已失效');}catch{}}
</script>
<template><div class="profile-page"><span class="studio-eyebrow">A LITTLE MORE YOU</span><h1>个人设置</h1><p>向别人介绍自己，也给自己的空间换个心情。</p><el-form v-if="p" label-position="top" class="profile-form" @submit.prevent="save"><section class="profile-panel"><div class="profile-avatar"><img :src="p.avatar" alt="我的头像"/><div><h2>{{p.name}}</h2><label class="avatar-upload">更换头像<input type="file" accept="image/png,image/jpeg,image/webp" @change="avatar"/></label><small>保存后，头像与简介可公开展示。</small></div></div><el-form-item label="昵称"><el-input v-model="p.name" maxlength="80" required/></el-form-item><el-form-item label="个人简介"><el-input v-model="p.bio" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="想让别人认识怎样的你？"/></el-form-item><el-form-item label="Git 平台"><el-select v-model="p.gitProvider"><el-option label="GitHub" value="github"/><el-option label="Gitee" value="gitee"/></el-select></el-form-item><el-form-item label="Git 用户名"><el-input v-model="p.gitUsername" maxlength="39" placeholder="填写用户名，不需要粘贴链接或密码"/></el-form-item></section><section class="profile-panel"><h2>空间外观</h2><p>主题、壁纸与动效统一在空间外观中设置。</p><RouterLink to="/appearance">布置我的空间 →</RouterLink><el-button type="primary" native-type="submit" :loading="busy">保存个人设置</el-button></section></el-form><GitCalendar/><section class="profile-panel password-panel"><h2>修改密码</h2><form @submit.prevent="changePassword"><el-input v-model="password.old" type="password" show-password placeholder="当前密码" autocomplete="current-password" required/><el-input v-model="password.password" type="password" show-password placeholder="新密码，至少 10 位" autocomplete="new-password" minlength="10" required/><el-button native-type="submit">更新密码</el-button></form></section></div></template>
<style scoped>.profile-page>p{color:var(--studio-muted);margin:12px 0 25px;font-size:13px}.profile-form{display:grid;grid-template-columns:1fr 1fr;gap:24px}.profile-panel{border:1px solid var(--studio-line);border-radius:20px;background:var(--studio-panel);padding:28px}.profile-avatar{display:flex;gap:20px;align-items:center;margin-bottom:25px}.profile-avatar img{width:78px;height:78px;object-fit:cover;border-radius:25px}.profile-avatar h2{margin-bottom:8px}.profile-avatar small{display:block;font-size:10px;color:var(--studio-muted);margin-top:7px}.avatar-upload{cursor:pointer;color:#8270a2}.avatar-upload input{display:none}.theme-choices{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0}.theme-choices button{border:2px solid var(--studio-line);border-radius:15px;padding:10px;background:transparent;color:inherit;text-align:left;cursor:pointer}.theme-choices .selected{border-color:#9280b2}.theme-mini{height:100px;border-radius:8px;margin-bottom:13px;overflow:hidden}.minimal-mini{display:flex;gap:8px;padding:20px 10px;background:#f1f2f7}.minimal-mini span{background:#d7d4e3;flex:1;border-radius:4px}.minimal-mini span:first-child{flex:.4;background:#b0a4c9}.cozy-mini{background:linear-gradient(0deg,#27344e55,#d9ab8d22),url('/assets/landscape-study.webp') center/cover;display:grid;place-items:center;color:white;font-size:32px}.theme-choices small{display:block;font-size:10px;line-height:1.6;margin:6px 0}.profile-panel>p{color:var(--studio-muted);font-size:12px;line-height:1.9;margin-bottom:18px}.profile-panel>a{display:block;margin-bottom:25px;font-size:12px}.password-panel form{display:flex;gap:15px;margin-top:20px}@media(max-width:850px){.profile-form{grid-template-columns:1fr}.profile-panel{padding:20px}.password-panel form{flex-direction:column}}</style>
